import math


def best_rational(num: int, den: int, max_den: int, side: int = 0) -> tuple[int, int]:
    if den == 0:
        raise ValueError("den must be nonzero")
    if max_den < 1:
        raise ValueError("max_den must be at least 1")
    if side not in (-1, 0, 1):
        raise ValueError("side must be -1, 0, or 1")

    if den < 0:
        num = -num
        den = -den

    g = math.gcd(abs(num), den)
    a = num // g
    b = den // g

    if b <= max_den:
        return (a, b)

    n = a // b
    r = a - n * b

    def _best_fraction_part(p: int, q: int, bound: int, want: int) -> tuple[int, int]:
        # 0 <= p < q, gcd(p, q) = 1, bound < q.
        # want == -1: maximum fraction <= p/q
        # want ==  1: minimum fraction >= p/q
        if p == 0:
            return (0, 1) if want == -1 else (1, 1)

        # Convergents of [0; ...]:
        # c_{-1} = 1/0, c_0 = 0/1
        p_prev, q_prev = 1, 0
        p_cur, q_cur = 0, 1

        x, y = p, q

        while True:
            k = y // x
            p_next = k * p_cur + p_prev
            q_next = k * q_cur + q_prev

            if q_next > bound:
                # p_cur / q_cur is the last convergent with denominator <= bound.
                lhs = p_cur * q
                rhs = p * q_cur
                if lhs < rhs:
                    cur_side = -1
                elif lhs > rhs:
                    cur_side = 1
                else:
                    cur_side = 0

                if cur_side == want:
                    return (p_cur, q_cur)

                t = (bound - q_prev) // q_cur
                return (p_prev + t * p_cur, q_prev + t * q_cur)

            p_prev, q_prev = p_cur, q_cur
            p_cur, q_cur = p_next, q_next

            rem = y - k * x
            if rem == 0:
                return (p_cur, q_cur)

            x, y = rem, x

    if side == -1:
        fp, fq = _best_fraction_part(r, b, max_den, -1)
        return (n * fq + fp, fq)

    if side == 1:
        fp, fq = _best_fraction_part(r, b, max_den, 1)
        return (n * fq + fp, fq)

    lp, lq = _best_fraction_part(r, b, max_den, -1)
    up, uq = _best_fraction_part(r, b, max_den, 1)

    lp_full = n * lq + lp
    up_full = n * uq + up

    diff_low = a * lq - lp_full * b
    diff_up = up_full * b - a * uq

    cmp = diff_low * uq - diff_up * lq

    if cmp < 0:
        return (lp_full, lq)
    if cmp > 0:
        return (up_full, uq)

    if lq < uq:
        return (lp_full, lq)
    if uq < lq:
        return (up_full, uq)

    if lp_full <= up_full:
        return (lp_full, lq)
    return (up_full, uq)
